// Bundles Mozilla Readability into a TS module as a string so it can be
// injected into the reader WebView. Run `npm run gen:readability` (from the
// project root) after
// upgrading @mozilla/readability.
const fs = require('fs');
const path = require('path');

const src = fs.readFileSync(require.resolve('@mozilla/readability/Readability.js'), 'utf8');
const out = path.resolve('src', 'reader', 'readability.generated.ts');
fs.writeFileSync(
  out,
  '// AUTO-GENERATED by scripts/gen-readability.js — do not edit.\n' +
    '/* eslint-disable */\n' +
    `export const READABILITY_JS = ${JSON.stringify(src)};\n`
);
console.log('wrote', path.relative(process.cwd(), out));
